#!/usr/bin/env bash
#
# sync-skills.sh — synchronize skills from a source folder to a destination folder
#
# Every subfolder of the source that contains a SKILL.md is copied to
# DESTINATION/<name>, adding, updating and removing files so each synced skill
# exactly matches its source. Skill folders that exist only in the destination
# (e.g. generated by the openspec tooling) are left untouched unless --mirror
# is passed.
#
# Uses rsync when available and falls back to pure bash + coreutils otherwise.

set -euo pipefail

SCRIPT_NAME="$(basename "$0")"

usage() {
  cat <<EOF
Usage: $SCRIPT_NAME [SOURCE] [DESTINATION] [options]

Synchronize skills from SOURCE to DESTINATION.

Arguments:
  SOURCE         skills folder to sync from   (default: <repo>/skills)
  DESTINATION    skills folder to sync into   (default: <repo>/.opencode/skills)

Options:
  -m, --mirror   also remove skills from DESTINATION that are not in SOURCE
  -h, --help     show this help and exit

Examples:
  $SCRIPT_NAME
  $SCRIPT_NAME ~/my-skills ~/project/.opencode/skills
EOF
}

positional=()
mirror=0
while [[ $# -gt 0 ]]; do
  case "$1" in
    -m|--mirror) mirror=1 ;;
    -h|--help) usage; exit 0 ;;
    -*)
      echo "$SCRIPT_NAME: unknown option: $1" >&2
      usage >&2
      exit 1
      ;;
    *) positional+=("$1") ;;
  esac
  shift
done

if ((${#positional[@]} > 2)); then
  echo "$SCRIPT_NAME: expected at most 2 arguments, got ${#positional[@]}" >&2
  usage >&2
  exit 1
fi

# defaults are relative to the repository root; passed paths are used as given
root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
src="${positional[0]:-$root/skills}"
dst="${positional[1]:-$root/.opencode/skills}"

[[ -d "$src" ]] || { echo "$SCRIPT_NAME: source folder not found: $src" >&2; exit 1; }
mkdir -p "$dst"

use_rsync=0
command -v rsync >/dev/null 2>&1 && use_rsync=1

# sync_dir <source> <destination>: make <destination> an exact copy of <source>
sync_dir() {
  local s="${1%/}" d="${2%/}" rel
  mkdir -p "$d"
  if ((use_rsync)); then
    rsync -a --delete "$s/" "$d/"
    return
  fi
  # copy every file and directory, preserving permissions
  while IFS= read -r -d '' rel; do
    if [[ -d "$s/$rel" ]]; then
      mkdir -p "$d/$rel"
    else
      mkdir -p "$d/$(dirname "$rel")"
      cp -p "$s/$rel" "$d/$rel"
    fi
  done < <(cd "$s" && find . -mindepth 1 -print0)
  # remove files in the destination that no longer exist in the source
  local stale=()
  mapfile -d '' stale < <(cd "$d" && find . -mindepth 1 -depth -print0)
  for rel in ${stale[@]+"${stale[@]}"}; do
    [[ -e "$s/$rel" || -L "$s/$rel" ]] || rm -rf "${d:?}/$rel"
  done
}

synced=0
skipped=0
for dir in "$src"/*/; do
  [[ -d "$dir" ]] || continue
  name="$(basename "$dir")"
  if [[ ! -f "$dir/SKILL.md" ]]; then
    echo "skip  $name (no SKILL.md)"
    skipped=$((skipped + 1))
    continue
  fi
  sync_dir "$dir" "$dst/$name"
  echo "sync  $name"
  synced=$((synced + 1))
done

if ((mirror)); then
  for dir in "$dst"/*/; do
    [[ -d "$dir" ]] || continue
    name="$(basename "$dir")"
    if [[ ! -d "$src/$name" ]]; then
      rm -rf "${dir:?}"
      echo "rm    $name (not in $src)"
    fi
  done
fi

echo "done: $synced synced, $skipped skipped -> $dst"
